var s = new OptimisticStore<string>();
s.Put("k", "v1", 0);
bool threw = false;
try { s.Put("k", "v2", 0); } catch (InvalidOperationException) { threw = true; }
Cj.True(threw, "stale expected version must throw");
Cj.Eq(s.TryGet("k").value, "v1", "original value preserved");
Cj.Eq(s.VersionOf("k"), 1, "version advanced once");

var s = new OptimisticStore<string>();
// The third write is ALREADY stale when submitted: it expects version 0,
// but the first write bumps 'a' to version 1 in the same round.
var writes = new List<(string, string, int)> { ("a", "x", 0), ("b", "y", 0), ("a", "x2", 0) };
int rounds = OptimisticStore<string>.SaveAll(s, writes, 5);
Cj.True(rounds >= 2, "stale write needs a second round");
Cj.Eq(s.TryGet("a").value, "x2", "stale write won after retry");
Cj.Eq(s.VersionOf("a"), 2, "a was written twice");
